sql.smartlist.add:
insert into flow.smartlist (name, company_object_type_id, share, owner_id, created_by_id)
values (:name, :companyObjectTypeId, false, :ownerId, :createdById)
returning id;

sql.smartlist.addField:
insert into flow.smartlist_field_assignment (smartlist_id, smartlist_field_id, custom_field_id, created_by_id, display_order)
values (:smartlistId, :smartlistFieldId, :customFieldId, :createdById, :displayOrder)
returning id;
